inline bool contains_pixel(int x, int y) {
    if (x<0 || y<0 || x>=WIDTH || y>=HEIGHT) return false;
    unsigned i=y*WIDTH+x; return (MASK[i/8] & (1u << (i%8))) != 0;
}
